// Package ratelimit implements a concurrency-safe token-bucket rate limiter.
package ratelimit

import (
	"errors"
	"fmt"
	"sync"
	"time"
)

// Clock reports the current time. It is an injection point for tests.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
// The zero value is not usable; construct with New.
type Limiter struct {
	mu       sync.Mutex
	tokens   float64
	last     time.Time
	rate     float64 // tokens per second
	burst    float64 // bucket capacity
	clock    Clock
	nowFn    func() time.Time // fast path when clock is the default
}

// New returns a Limiter that admits up to burst events, refilled at rate
// events per second. rate must be > 0 and burst must be >= 1.
func New(rate float64, burst int) (*Limiter, error) {
	return NewWithClock(rate, burst, nil)
}

// NewWithClock is New with an injectable Clock. A nil clock uses the
// real system clock.
func NewWithClock(rate float64, burst int, clock Clock) (*Limiter, error) {
	if rate <= 0 {
		return nil, fmt.Errorf("rate must be > 0, got %v", rate)
	}
	if burst < 1 {
		return nil, fmt.Errorf("burst must be >= 1, got %d", burst)
	}
	if clock == nil {
		clock = realClock{}
	}
	l := &Limiter{
		tokens: float64(burst),
		rate:   rate,
		burst:  float64(burst),
		clock:  clock,
	}
	if rc, ok := clock.(realClock); ok {
		l.nowFn = rc.Now
	}
	return l, nil
}

// advance refills tokens up to now. Caller must hold l.mu.
func (l *Limiter) advance(now time.Time) {
	if l.last.IsZero() {
		l.last = now
		return
	}
	elapsed := now.Sub(l.last)
	if elapsed <= 0 {
		return
	}
	l.tokens += elapsed.Seconds() * l.rate
	if l.tokens > l.burst {
		l.tokens = l.burst
	}
	l.last = now
}

// AllowN reports whether n tokens may be consumed at time now.
// It never blocks; if fewer than n tokens are available it returns false
// and consumes nothing.
func (l *Limiter) AllowN(now time.Time, n int) bool {
	if n < 1 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	l.advance(now)
	need := float64(n)
	if l.tokens < need {
		return false
	}
	l.tokens -= need
	return true
}

// Allow reports whether one token may be consumed now.
func (l *Limiter) Allow() bool {
	return l.AllowN(l.now(), 1)
}

func (l *Limiter) now() time.Time {
	if l.nowFn != nil {
		return l.nowFn()
	}
	return l.clock.Now()
}

// RetryAfter returns the duration the caller should wait before a request
// for n tokens could succeed, measured from now. It returns 0 if the
// request would succeed now.
func (l *Limiter) RetryAfter(now time.Time, n int) time.Duration {
	if n < 1 {
		return 0
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	l.advance(now)
	need := float64(n) - l.tokens
	if need <= 0 {
		return 0
	}
	return time.Duration(need / l.rate * float64(time.Second))
}

// ErrInvalidConfig is returned by New for invalid parameters; retained for
// callers that wish to test with errors.Is. New wraps it with details.
